// src/facets/hero.rs — the facet's own module; src/main.rs adds its two FACET WIRING lines.
// World (src/main.rs) holds hero: Option<Animator>, body: Option<Character>, clips: Option<HeroClips>,
// wish: Vec3 and attack: bool (the controls facet sets the last two each tick).
use super::{HeroClips, World};
use genex::prelude::*;
use genex::CharacterParams;

pub fn wire(game: &mut Game<World>) {
    game.on_reset(|sim, _, _, gfx| {
        let Ok(hero) = gfx.character("characters/hero.glb") else { return }; // animation-asset-invalid
        let (Some(idle), Some(walk), Some(slash)) = (hero.clip("Idle"), hero.clip("Walk"), hero.clip("Sword_Attack")) else { return };
        let Ok(mut animator) = Animator::simple(&hero) else { return };
        animator.play(idle);
        // Placed by its feet on the floor (y 0 here), never by its centre.
        let Ok(body) = Character::spawn(&mut sim.physics, vec3(0.0, 0.0, 4.0), CharacterParams::default()) else { return };
        sim.world.hero = Some(animator);
        sim.world.body = Some(body);
        sim.world.clips = Some(HeroClips { idle, walk, slash });
    });
    game.on_update(|sim, ctx| {
        let (world, physics) = sim.split();
        let (Some(animator), Some(body), Some(clips)) = (world.hero.as_mut(), world.body.as_mut(), world.clips) else { return };
        // The capsule walks, slides along walls and climbs steps; the model follows it.
        body.drive(physics, CharacterMotion::Velocity { wish: world.wish, jump: false }, ctx.dt);
        animator.crossfade(if world.wish.length() > 0.1 { clips.walk } else { clips.idle }, 0.25); // every tick is fine
        if world.attack {
            animator.play_once(clips.slash); // blends back into walk or idle at its end
        }
        animator.update(ctx.dt); // only the simulation moves an animator
    });
    game.on_draw(|sim, frame, _| {
        let (Some(animator), Some(body)) = (&sim.world.hero, &sim.world.body) else { return };
        frame.tag("hero");
        frame.character(animator, body.transform().into()); // the model's feet are the capsule's
    });
    game.probe("hero", |sim| sim.world.hero.as_ref().map_or(Value::Null, Animator::probe));
    // Grounded: the feet's height beside the floor's, which a check compares.
    game.probe("heroFeet", |sim| json!({ "feet": sim.world.body.as_ref().map(|body| body.feet().y), "ground": 0.0 }));
}
